#include <bits/stdc++.h>
using namespace std;
int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);
    vector<pair<int,int>> ops;
    auto apply=[&](int x,int y){
        ops.push_back({x,y});
        vector<int> q(n);
        for(int i=0;i<y;i++) q[i]=p[n-y+i];
        for(int i=0;i<n-x-y;i++) q[y+i]=p[x+i];
        for(int i=0;i<x;i++) q[n-x+i]=p[i];
        p=q;
    };
    for(int t=0;t<n;t++){
        int pos=-1;
        for(int i=t;i<n;i++) if(p[i]==t+1){pos=i;break;}
        if(pos==t) continue;
        int rem=n-t;
        // Work within p[t..n-1] conceptually, but ops are global
        // Move p[pos] to p[t]
        if(pos!=n-1){
            int x=pos+1, y=1;
            if(x+y<n) apply(x,y);
            else{ x=pos; y=n-pos-1; if(x>0&&y>0&&x+y<n) apply(x,y); else{ apply(1,1); for(int i=t;i<n;i++) if(p[i]==t+1){pos=i;break;} if(pos!=n-1){x=pos+1;y=1;if(x+y<n)apply(x,y);}}}
        }
        // now at n-1
        if(t==n-1) continue;
        int x=n-1-t, y=1;
        if(x>0&&y>0&&x+y<n) apply(x,y);
        // now at position 0, need position t
        if(t>0){
            x=1; y=t;
            if(x>0&&y>0&&x+y<n) apply(x,y);
        }
    }
    printf("%d\n",(int)ops.size());
    for(auto&[a,b]:ops) printf("%d %d\n",a,b);
}
